import React from 'react';
import styled from 'styled-components';

const Links = React.forwardRef((props, ref) => {
    return (
        <MainBox>
            <Title>Pobierz wzory niezbędnych dokumentów</Title>
            <Row>
                <SectionColumn>
                    <TitleBox>
                        <h2>Umowy w działalności gospodarczej</h2>
                    </TitleBox>
                    <Document>lalal</Document>
                </SectionColumn>
                <SectionColumn>
                    <TitleBox>
                        <h2>Formularze</h2>
                    </TitleBox>
                </SectionColumn>
            </Row>
            <Row>
                <SectionColumn>
                    <TitleBox>
                        <h2>Umowy</h2>
                    </TitleBox>
                </SectionColumn>
                <SectionColumn>
                    <TitleBox>
                        <h2>Pisma</h2>
                    </TitleBox>
                </SectionColumn>
            </Row>
        </MainBox>
    );
});

export default Links

const MainBox = styled.div`
    padding: 48px;
    background-color: #f8f8f8;
`;

const Row = styled.div`
    display: flex;
    flex-direction: row;
    justify-content: space-between;
    padding-bottom: 48px;
`;

const SectionColumn = styled.div`
    display: flex;
    background-color: red;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    width: 100%;
`;

const TitleBox = styled.div`
    height: 100px;
    width: 90%;
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: #fff;
    border: 5px solid #D5992E;
    border-radius: 25px;
    box-shadow: -20px 20px #D5992E;
    margin-bottom: 20px;
    margin-left: 20px;
    padding: 24px;
`;

const Title = styled.h1`
    margin-top: 36px;
    text-align: center;
    padding-bottom: 96px;
`;

const Document = styled.a`
    font-family: 'Source Sans Pro', sans-serif;
    font-size: 1.25rem;
    padding: 48px;
`;
